    public function getSourceContext(): Source
    {
        return new Source("{% extends 'base.html.twig' %}

{% block title %}Log in{% endblock %}

{% block header %}{% endblock %}

{% block body %}
<div class=\"d-flex justify-content-center align-items-center vh-200\">
      
<div class=\"card p-4 shadow-lg\" style=\"width: 850px;\">
<form method=\"post\">
    {% if error %}
        <div class=\"alert alert-danger\">{{ error.messageKey|trans(error.messageData, 'security') }}</div>
    {% endif %}

    {% if app.user %}
        <div class=\"mb-3\">
            You are logged in as {{ app.user.userIdentifier }}, <a href=\"{{ path('app_logout') }}\">Logout</a>
        </div>
    {% endif %}

    <h1 class=\"h3 mb-3 font-weight-normal\">Please sign in</h1>
    <label for=\"inputEmail\">Email</label>
    <input type=\"email\" value=\"{{ last_username }}\" name=\"email\" id=\"inputEmail\" class=\"form-control\" autocomplete=\"email\" required autofocus>
    <label for=\"inputPassword\">Password</label>
    <input type=\"password\" name=\"password\" id=\"inputPassword\" class=\"form-control\" autocomplete=\"current-password\" required>

    <input type=\"hidden\" name=\"_csrf_token\"
           value=\"{{ csrf_token('authenticate') }}\"
    >

    <div class=\"checkbox mb-3\">
        <label>
            <input type=\"checkbox\" name=\"_remember_me\"> Remember me
        </label>
    </div>



    <div class=\"d-flex justify-content-center\">
    <button class=\"btn btn-lg btn-primary\" type=\"submit\">
        Login
    </button>
</div>


    <p>you don't have an account? <a href=\"{{ path('app_register') }}\">click here to register</a></p>
</form>
</div>
</div>

{% endblock %}
", "security/login.html.twig", "D:\\artistic-main\\artistic-main\\templates\\security\\login.html.twig");
